import{prepare}from'./browser.js';import{accountFixture}from'./account.js';
export async function setup(page,{invite=true,wrongEmail=false,empty=false}={}){await prepare(page,{lockAuthFixture:true,records:empty?[]:undefined});await accountFixture(page,{provider:'email',photo:false,plan:'free'});await page.addInitScript(({wrongEmail})=>{const base=window.supabase.createClient;window.__qaCalls=[];window.supabase.createClient=(...args)=>{const api=base(...args),rpc=api.rpc,state=()=>JSON.parse(localStorage.getItem('__qa_membership')||'null'),access=()=>({plan:state()?.plan||'free',beta:false,routeLimit:state()?.plan==='pro'?null:state()?.plan==='plus'?20:3,routeCount:0,portfolioCount:1,portfolioLimit:state()?.plan==='pro'?null:state()?.plan==='plus'?3:1,qa:!!state(),qaExpiresAt:'2026-12-30T00:00:00Z',qaOperator:false});api.rpc=async(name,p)=>{if(name==='traxelo_plan_access')return{data:access()};if(name==='rotamapa_redeem_test_invite'){window.__qaCalls.push(name);if(wrongEmail)return{error:{message:'Este convite exige o e-mail autorizado e confirmado.'}};if(p.p_token!=='a'.repeat(64))return{error:{message:'Convite inválido'}};if(!state())localStorage.setItem('__qa_membership',JSON.stringify({plan:'free'}));return{data:access()};}if(name==='rotamapa_simulate_upgrade'){window.__qaCalls.push({name,...p});const current=state();if(!current)return{error:{message:'Simulação disponível somente para contas de teste autorizadas.'}};if(!p.p_reset&&!((current.plan==='free'&&p.p_plan==='plus')||(current.plan==='plus'&&p.p_plan==='pro')||current.plan===p.p_plan))return{error:{message:'Etapa inválida'}};localStorage.setItem('__qa_membership',JSON.stringify({plan:p.p_plan}));return{data:access()};}return rpc(name,p);};return api;};},{wrongEmail});if(empty)await page.addInitScript(()=>{const base=supabase.createClient;supabase.createClient=(...args)=>{const c=base(...args),from=c.from;c.from=table=>{if(table!=='rotamapa_portfolios')return from(table);let patch=null;const row=()=>JSON.parse(localStorage.getItem('__qa_portfolio')||'{"id":"00000000-0000-4000-8000-000000000000","name":"Carteira inicial","revision":1}'),result=()=>{const r=row();if(patch){Object.assign(r,patch);localStorage.setItem('__qa_portfolio',JSON.stringify(r));}return{data:patch?r:[r],error:null};},q={then:yes=>Promise.resolve(result()).then(yes),single:async()=>result(),update:p=>{patch=p;return q;}};for(const m of ['select','eq','order','range','upsert'])q[m]=()=>q;return q;};return c;};});await page.goto(invite?'/#rm-invite='+'a'.repeat(64):'/');await page.locator('body.traxio-ui-ready').waitFor();}
